mapper.sql:
WHERE w.company_id=#{company}
 AND w.created_at >=CAST(#{q.startUtc} AS timestamp) AND w.created_at <CAST(#{q.endUtc} AS timestamp)
 AND w.archived=false
 AND COALESCE(w.is_demo,false)=false
 AND w.asset_id=#{q.assetId}
 AND w.status=#{q.statusCode}
 AND w.priority=#{q.priorityCode}

  AND EXISTSAND NOT EXISTS
  (SELECT 1 FROM meter_trigger_execution me WHERE me.work_order_id=w.id AND me.company_id=w.company_id)
